import json
from copy import deepcopy

def solve():
    houses = 6
    categories = {
        "Name": ["Alice", "Peter", "Eric", "Bob", "Arnold", "Carol"],
        "cigar": ["pall mall", "yellow monster", "dunhill", "blue master", "prince", "blends"],
        "music": ["hip hop", "jazz", "country", "pop", "classical", "rock"],
        "drink": ["water", "milk", "boba tea", "tea", "root beer", "coffee"],
        "mother": ["Kailyn", "Penny", "Janelle", "Holly", "Sarah", "Aniya"],
        "lunch": ["soup", "pizza", "spaghetti", "stir fry", "stew", "grilled cheese"]
    }

    # Map each item to its category
    var_to_cat = {}
    for cat, items in categories.items():
        for it in items:
            var_to_cat[it] = cat

    # Variables are all items; domains are positions 0..5
    all_items = list(var_to_cat.keys())
    domains = {v: set(range(houses)) for v in all_items}

    # Assignment maps item -> position (0-based), unassigned items not present
    assignment = {}

    # Helper constraint builders
    def at_pos(a, pos):
        def c(asg):
            if a in asg:
                return asg[a] == pos
            # simple domain pruning
            return True
        return c

    def not_at(a, pos):
        def c(asg):
            if a in asg:
                return asg[a] != pos
            return True
        return c

    def equal(a, b):
        def c(asg):
            if a in asg and b in asg:
                return asg[a] == asg[b]
            return True
        return c

    def direct_left(a, b):  # a immediately left of b
        def c(asg):
            a_assigned = a in asg
            b_assigned = b in asg
            if a_assigned and asg[a] == houses - 1:
                return False
            if b_assigned and asg[b] == 0:
                return False
            if a_assigned and b_assigned:
                return asg[a] + 1 == asg[b]
            return True
        return c

    def right_of(a, b):  # a somewhere right of b
        def c(asg):
            a_assigned = a in asg
            b_assigned = b in asg
            if b_assigned and not a_assigned and asg[b] == houses - 1:
                return False
            if a_assigned and b_assigned:
                return asg[a] > asg[b]
            return True
        return c

    def left_of(a, b):  # a somewhere left of b
        def c(asg):
            a_assigned = a in asg
            b_assigned = b in asg
            if a_assigned and not b_assigned and asg[a] == houses - 1:
                return False
            if a_assigned and b_assigned:
                return asg[a] < asg[b]
            return True
        return c

    def apart_by_n(a, b, n):
        def c(asg):
            a_assigned = a in asg
            b_assigned = b in asg
            if a_assigned and b_assigned:
                return abs(asg[a] - asg[b]) == n
            # Partial feasibility check
            if a_assigned:
                pos = asg[a]
                if pos - n < 0 and pos + n >= houses:
                    return False
            if b_assigned:
                pos = asg[b]
                if pos - n < 0 and pos + n >= houses:
                    return False
            return True
        return c

    # All-different per category
    def all_diff_constraint(asg):
        for cat, items in categories.items():
            seen = {}
            for it in items:
                if it in asg:
                    pos = asg[it]
                    if pos in seen:
                        return False
                    seen[pos] = it
        return True

    constraints = []

    # Apply direct clues as constraints

    # 1. Carol directly left of grilled cheese.
    constraints.append(direct_left("Carol", "grilled cheese"))

    # 2. Eric is not in the second house. (index 1)
    constraints.append(not_at("Eric", 1))

    # 3. Holly is somewhere to the right of Carol.
    constraints.append(right_of("Holly", "Carol"))

    # 4. Grilled cheese right of rock.
    constraints.append(right_of("grilled cheese", "rock"))

    # 5. Eric directly left of Carol.
    constraints.append(direct_left("Eric", "Carol"))

    # 6. Pop not in third house (index 2).
    constraints.append(not_at("pop", 2))

    # 7. Eric is country.
    constraints.append(equal("Eric", "country"))

    # 8. Classical in sixth house (index 5).
    constraints.append(at_pos("classical", 5))

    # 9. Coffee drinker is Bob.
    constraints.append(equal("coffee", "Bob"))

    # 10. Blends smoker is Peter.
    constraints.append(equal("blends", "Peter"))

    # 11. Stew not in fifth house (index 4).
    constraints.append(not_at("stew", 4))

    # 12. Root beer directly left of Janelle.
    constraints.append(direct_left("root beer", "Janelle"))

    # 13. Two houses between Sarah and yellow monster.
    constraints.append(apart_by_n("Sarah", "yellow monster", 3))

    # 14. Eric is tea drinker.
    constraints.append(equal("tea", "Eric"))

    # 15. Pall Mall right of stir fry.
    constraints.append(right_of("pall mall", "stir fry"))

    # 16. Soup is Bob.
    constraints.append(equal("soup", "Bob"))

    # 17. Hip hop directly left of Kailyn.
    constraints.append(direct_left("hip hop", "Kailyn"))

    # 18. Arnold right of Kailyn.
    constraints.append(right_of("Arnold", "Kailyn"))

    # 19. Water directly left of blue master.
    constraints.append(direct_left("water", "blue master"))

    # 20. Spaghetti somewhere to the left of blends.
    constraints.append(left_of("spaghetti", "blends"))

    # 21. Sarah directly left of jazz.
    constraints.append(direct_left("Sarah", "jazz"))

    # 22. Hip hop directly left of root beer.
    constraints.append(direct_left("hip hop", "root beer"))

    # 23. Water is stew.
    constraints.append(equal("water", "stew"))

    # 24. Dunhill not in the second house (index 1).
    constraints.append(not_at("dunhill", 1))

    # 25. Milk is Janelle.
    constraints.append(equal("milk", "Janelle"))

    # 26. Eric is Aniya.
    constraints.append(equal("Eric", "Aniya"))

    # Derived equalities
    # From 17 and 22: Kailyn and root beer are the same house.
    constraints.append(equal("Kailyn", "root beer"))

    # Pre-narrow domains based on at_pos/not_at constraints for a bit more pruning
    # (optional but helps)
    # We can intersect domains accordingly
    for c in constraints:
        # Only handle simple at_pos/not_at here
        if getattr(c, "__name__", "") == "c":
            pass  # anonymous; skip
    # We'll instead directly adjust domains for the known fixed positions:
    domains["classical"] = {5}

    # Also mark impossible ends for direct-left anchors if we want to prune domains:
    # If A directly left of B, A cannot be at last, B cannot be at first
    direct_left_pairs = [
        ("Carol", "grilled cheese"),
        ("Eric", "Carol"),
        ("root beer", "Janelle"),
        ("hip hop", "Kailyn"),
        ("hip hop", "root beer"),
        ("water", "blue master"),
        ("Sarah", "jazz"),
    ]
    for a, b in direct_left_pairs:
        domains[a] -= {houses - 1}
        domains[b] -= {0}

    # Not-at constraints
    domains["Eric"] -= {1}
    domains["pop"] -= {2}
    domains["stew"] -= {4}
    domains["dunhill"] -= {1}

    # Utility: check all constraints and all-different
    def check_all(asg):
        if not all_diff_constraint(asg):
            return False
        for c in constraints:
            if not c(asg):
                return False
        return True

    # MRV: choose next variable (item) with smallest domain considering current conflicts
    def select_unassigned_var(asg, doms):
        unassigned = [v for v in all_items if v not in asg]
        # Prefer items with singleton domains first
        unassigned.sort(key=lambda v: len(doms[v]))
        return unassigned[0] if unassigned else None

    # Order values by least-constraining value heuristic (optional simple: sorted)
    def order_domain_values(var, asg, doms):
        return list(sorted(doms[var]))

    # Forward checking: when we assign var -> val, we ensure category uniqueness by
    # removing val from other items in same category. We'll do this via a local copy of domains.
    def backtrack(asg, doms):
        if len(asg) == len(all_items):
            if check_all(asg):
                return asg
            return None

        var = select_unassigned_var(asg, doms)
        if var is None:
            return None

        for val in order_domain_values(var, asg, doms):
            # Check category uniqueness quickly
            cat = var_to_cat[var]
            conflict = False
            for other in categories[cat]:
                if other != var and other in asg and asg[other] == val:
                    conflict = True
                    break
            if conflict:
                continue

            # Tentative assign
            new_asg = dict(asg)
            new_asg[var] = val

            # New domains copy
            new_doms = deepcopy(doms)
            # Assign var to single value
            new_doms[var] = {val}
            # Enforce all-different in category: remove val from others
            for other in categories[cat]:
                if other != var and other not in new_asg:
                    if val in new_doms[other]:
                        new_doms[other].remove(val)
                        if not new_doms[other]:
                            # dead domain
                            new_asg = None
                            break
            if new_asg is None:
                continue

            # Early constraint check
            if not check_all(new_asg):
                continue

            # Continue
            result = backtrack(new_asg, new_doms)
            if result is not None:
                return result

        return None

    solution_assignment = backtrack(assignment, domains)
    if solution_assignment is None:
        raise RuntimeError("No solution found")

    # Build house mapping: for each house index, get attribute per category
    # For each category, find the item at that position
    house_rows = []
    for pos in range(houses):
        row = {}
        row["House"] = str(pos + 1)
        for cat, items in categories.items():
            found_item = None
            for it in items:
                if solution_assignment[it] == pos:
                    found_item = it
                    break
            if found_item is None:
                raise RuntimeError(f"Incomplete assignment for house {pos+1}, category {cat}")
            row[cat] = found_item
        house_rows.append(row)

    # Prepare JSON output
    header = ["House", "Name", "cigar", "music", "drink", "mother", "lunch"]
    rows = []
    for r in house_rows:
        rows.append([r["House"], r["Name"], r["cigar"], r["music"], r["drink"], r["mother"], r["lunch"]])

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    solve()
